import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec4, uniform, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.3,
    side: THREE.FrontSide,
  });

  const imageUrl = '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const rectMin = vec2(0.0, 0.0);
  const rectMax = vec2(1.0, 0.625); // 320/512

  const remappedUv = vec2(
    uvNode.x,
    rectMin.y.add(uvNode.y.mul(rectMax.y.sub(rectMin.y)))
  );

  const texSample = texture(map, remappedUv);

  const hoverUniform = uniform(0.0);
  const accentColor = new THREE.Color('#ff2a38');
  const edgeMix = uv().x.smoothstep(0.0, 0.03).oneMinus()
    .add(uv().x.smoothstep(0.97, 1.0))
    .clamp(0.0, 1.0);

  const finalColor = mix(texSample.rgb, vec4(accentColor.r, accentColor.g, accentColor.b, 1.0).rgb, edgeMix.mul(hoverUniform));

  material.colorNode = vec4(finalColor, texSample.a);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  mesh.name = 'hub-journal-card-3';

  mesh.userData = mesh.userData || {};

  // Data binding: stock badge indicator (small plane)
  const badgeGeometry = new THREE.PlaneGeometry(0.14, 0.14);
  const badgeMaterial = new THREE.MeshBasicNodeMaterial({ transparent: true });
  const badgeColorUniform = uniform(new THREE.Color('#16161d'));
  badgeMaterial.colorNode = vec4(badgeColorUniform, 1.0);
  const badgeMesh = new THREE.Mesh(badgeGeometry, badgeMaterial);
  badgeMesh.position.set(width / 2 - 0.12, height / 2 - 0.12, 0.01);
  mesh.add(badgeMesh);

  mesh.userData.setStockStatus = (inStock) => {
    badgeColorUniform.value.set(inStock ? '#2ecc71' : '#ff2a38');
  };
  // default state
  mesh.userData.setStockStatus(true);

  // Interaction state
  let baseY = mesh.position.y;
  let hoverTween = null;
  let pressTween = null;

  const onHoverStart = () => {
    hoverUniform.value = 1.0;
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverEnd = () => {
    hoverUniform.value = 0.0;
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onClick = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });

    if (mesh.userData.emit) {
      mesh.userData.emit('hub-journal.select', { id: 'hub-journal-card-3' });
    }
  };

  mesh.userData.handlers = {
    onPointerOver: onHoverStart,
    onPointerOut: onHoverEnd,
    onClick,
  };

  mesh.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    badgeGeometry.dispose();
    badgeMaterial.dispose();
    if (map) map.dispose();
  };

  return mesh;
}
